/*
 * Mirrors the JSON schema files exactly. Generated by hand from the schema;
 * if the schema changes, change this file first, then the screens.
 * Never edit app/src/main/assets/content by hand — run tools/build_content.py.
 */

/** App / prose language. */
enum class Lang { te, hi, en }

/** How sacred text is shown: the user's script, Devanagari, or IAST. */
enum class TextView { Script, Devanagari, Iast }

@Serializable
data class Localized(val te: String? = null, val hi: String? = null, val en: String? = null) {
    /** Never returns blank if any language exists: chosen → en → hi → te. */
    fun pick(lang: Lang): String = when (lang) {
        Lang.te -> te ?: en ?: hi
        Lang.hi -> hi ?: en ?: te
        Lang.en -> en ?: hi ?: te
    } ?: ""
}

@Serializable
data class Sacred(val sa: String, val iast: String, val te: String) {
    /** Script view follows the app language: te → Telugu, hi → Devanagari, en → IAST. */
    fun pick(view: TextView, lang: Lang): String = when (view) {
        TextView.Devanagari -> sa
        TextView.Iast -> iast
        TextView.Script -> when (lang) {
            Lang.te -> te
            Lang.hi -> sa
            Lang.en -> iast
        }
    }
}

