// ---------- calendar ----------
@Serializable data class CalendarDay(
    val date: String,                // yyyy-MM-dd (IST civil day)
    val sunrise: String, val sunset: String,             // HH:mm IST
    val tithi: Int,                  // at sunrise: 1–15 śukla, 16–30 kṛṣṇa, 30 = amāvāsyā
    @SerialName("tithi_ends") val tithiEnds: String? = null,
    val nakshatra: Int, @SerialName("nakshatra_ends") val nakshatraEnds: String? = null,
    val masa: Int, val adhika: Boolean,
    @SerialName("moon_rashi") val moonRashi: Int, @SerialName("moon_pct") val moonPct: Int,
    val observances: List<String> = emptyList(),
) {
    val isShukla get() = tithi <= 15
    /** 1–15 within the paksha (amāvāsyā reports 15 with isShukla = false). */
    val tithiInPaksha get() = if (tithi <= 15) tithi else tithi - 15
}
@Serializable data class SamvatsaraRef(val year: Int, val id: String, val n: Int)
@Serializable data class CalendarYear(val city: String, val samvatsara: SamvatsaraRef, val start: String, val end: String, val days: List<CalendarDay>)

